using System.Diagnostics;using OrderProcessing.Shared.Models;using OrderProcessing.Shared.Storage;using OrderProcessing.Phase1;using OrderProcessing.Phase2;using OrderProcessing.Phase3;using OrderProcessing.Phase4;
namespace OrderProcessing;
public static class Program
{
 public static async Task Main(string[] args)
 {
  string mode=args.FirstOrDefault()?.ToLowerInvariant()??Menu();using var cts=new CancellationTokenSource();Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;cts.Cancel();};int ci=Array.IndexOf(args,"--cancel-after");if(ci>=0&&ci+1<args.Length)cts.CancelAfter(int.Parse(args[ci+1]));
  try{if(mode is "phase1" or "all")await Phase1(cts.Token);if(mode is "phase2" or "all")await Phase2(cts.Token);if(mode is "phase3" or "all")await Phase3(cts.Token);if(mode is "phase4" or "all")await Phase4(cts.Token);}catch(OperationCanceledException){Console.WriteLine("Run cancelled");}
 }
 static string Menu(){Console.WriteLine("1. Phase 1\n2. Phase 2\n3. Phase 3\n4. Phase 4\n5. All");return (Console.ReadLine()??"1") switch{"2"=>"phase2","3"=>"phase3","4"=>"phase4","5"=>"all",_=>"phase1"};}
 static (JsonFileStore,CustomerRepository,ProductRepository,CouponRepository,IncomingOrderRepository) Basic(){var s=new JsonFileStore();return(s,new(s),new(s),new(s),new(s));}
 static async Task Phase1(CancellationToken ct)
 {
  await DataSeeder.ResetAsync(ct);var(s,c,p,cp,inc)=Basic();var repo=new OrderRepository(s);var validator=new OrderValidator(c,p,cp,repo);var list=await inc.GetAllAsync(ct);var sw=Stopwatch.StartNew();foreach(var o in list)await validator.ValidateOrderAsync(o,ct);sw.Stop();var all=await repo.GetAllAsync(ct);Console.WriteLine($"===== Validation Summary =====\nTotal Orders: {all.Count}\nValidated: {all.Count(x=>x.Status==OrderStatus.Validated)}\nRejected: {all.Count(x=>x.Status==OrderStatus.Rejected)}");foreach(var o in all.Where(x=>x.Status==OrderStatus.Rejected))Console.WriteLine($"- Order #{o.Id}: {o.FailureReason}");Console.WriteLine($"Async Time: {sw.Elapsed.TotalSeconds:F1} seconds\norders.json now contains {all.Count} records.");
 }
 static async Task Phase2(CancellationToken ct)
 {
  await DataSeeder.ResetAsync(ct);var(s,c,p,cp,inc)=Basic();var repo=new OrderRepository(s);var valid=new OrderValidator(c,p,cp,repo);var list=await inc.GetAllAsync(ct);var vt=list.Select(o=>valid.ValidateOrderAsync(o,ct)).ToList();foreach(var t in vt)await t;var pricer=new OrderPricer(new(p,c,cp,[7]));var invoice=new InvoiceGenerator();var jobs=list.Where(x=>x.Status==OrderStatus.Validated).Select(async o=>{var held=new List<OrderItem>();try{foreach(var i in o.Items){if(!await p.ReserveStockAsync(i.ProductId,i.Quantity,ct)){foreach(var h in held)await p.ReleaseStockAsync(h.ProductId,h.Quantity,ct);o.Status=OrderStatus.Rejected;o.FailureReason="Insufficient stock";await repo.SaveAsync(o,ct);return;}held.Add(i);}await pricer.PriceOrderAsync(o,ct);await invoice.GenerateAsync(o,ct);o.Status=OrderStatus.Completed;await repo.SaveAsync(o,ct);}catch(Exception ex) when(ex is not OperationCanceledException){foreach(var h in held)await p.ReleaseStockAsync(h.ProductId,h.Quantity,CancellationToken.None);o.Status=OrderStatus.Failed;o.FailureReason=ex.Message;await repo.SaveAsync(o,CancellationToken.None);}}).ToList();Console.WriteLine($"First task status: {jobs[0].Status}");foreach(var t in jobs)await t;var all=await repo.GetAllAsync(ct);Console.WriteLine($"Phase 2: {all.Count(x=>x.Status==OrderStatus.Completed)} completed, {all.Count(x=>x.Status==OrderStatus.Rejected)} rejected, {all.Count(x=>x.Status==OrderStatus.Failed)} failed");
 }
 static async Task Phase3(CancellationToken ct)
 {
  await DataSeeder.ResetAsync(ct);var(s,c,p,cp,inc)=Basic();var repo=new OrderRepository(s,[13]);var proc=new OrderProcessor(new(c),new(p),new(new(p,c,cp)),new PaymentGateway(s,[5],[8]),repo,new EmailService(s,new(){{3,2},{17,int.MaxValue}}),s);var list=await inc.GetAllAsync(ct);var tasks=list.Select(o=>proc.ProcessOrderAsync(o,ct)).ToList();foreach(var t in tasks)try{await t;}catch(OperationCanceledException){throw;}var all=await new OrderRepository(s).GetAllAsync(ct);foreach(var o in all.OrderBy(x=>x.Id))Console.WriteLine($"{o.Id,2} {o.Status,-13} {o.TotalAmount,8:F2} {o.FailureReason}");
 }
 static async Task Phase4(CancellationToken ct)
 {
  await DataSeeder.ResetAsync(ct);var(s,c,p,cp,inc)=Basic();var repo=new OrderRepository(s,[13]);var proc=new OrderProcessor(new(c),new(p),new(new(p,c,cp)),new PaymentGateway(s,[5],[8]),repo,new EmailService(s,new(){{3,2},{17,int.MaxValue}}),s);var list=await inc.GetAllAsync(ct);var started=Stopwatch.StartNew();var tasks=list.Select(async o=>(Order:o,Ok:await proc.ProcessOrderAsync(o,ct))).ToList();int count=0;await foreach(var finished in Task.WhenEach(tasks)){var x=await finished;Console.WriteLine($"[{++count,2}/20] Order #{x.Order.Id} -> {x.Order.Status} ({x.Order.FailureReason}) after {started.Elapsed.TotalSeconds:F1} s");}
  var dash=new CustomerDashboardService(s,c,[99]);var dsw=Stopwatch.StartNew();var d=await dash.LoadAsync(3,ct);Console.WriteLine($"Dashboard #3: {d.Orders.Count} orders, {d.Payments.Count} payments, {d.Emails.Count} emails in {dsw.ElapsedMilliseconds} ms");
  var quotes=new ShippingQuoteService([new ShippingCarrier("FastShip",500,1500,1),new ShippingCarrier("CairoExpress",300,2000,.95m,[2,4]),new ShippingCarrier("NileCourier",800,1200,1.1m)]);foreach(var o in list.Take(5)){var q=await quotes.GetFastestQuoteAsync(o,ct);Console.WriteLine($"Quote #{o.Id}: {q.Carrier} {q.Price:F2} in {q.ElapsedMs} ms");}
  var sw=Stopwatch.StartNew();var seq=new List<int>();for(int id=1;id<=10000;id++)if(Score(id)>=90)seq.Add(id);var seqMs=sw.ElapsedMilliseconds;var bag=new System.Collections.Concurrent.ConcurrentBag<int>();var threads=new System.Collections.Concurrent.ConcurrentDictionary<int,byte>();sw.Restart();await Parallel.ForEachAsync(Enumerable.Range(1,10000),new ParallelOptions{MaxDegreeOfParallelism=Environment.ProcessorCount,CancellationToken=ct},(id,token)=>{threads.TryAdd(Environment.CurrentManagedThreadId,0);if(Score(id)>=90)bag.Add(id);return ValueTask.CompletedTask;});Console.WriteLine($"Fraud: {bag.Count} flagged; sequential {seqMs} ms; parallel {sw.ElapsedMilliseconds} ms; threads {threads.Count}/{Environment.ProcessorCount}");
  await s.WriteAsync<EmailMessage>(DataFiles.Emails,[],ct);var emailService=new EmailService(s);int active=0,max=0;sw.Restart();await Parallel.ForEachAsync(Enumerable.Range(1001,30),new ParallelOptions{MaxDegreeOfParallelism=4,CancellationToken=ct},async(id,token)=>{int now=Interlocked.Increment(ref active);InterlockedExtensions.Max(ref max,now);try{await emailService.SendConfirmationAsync(new Order{Id=id},new Customer{Email=$"test{id}@example.com"},token);}finally{Interlocked.Decrement(ref active);}});Console.WriteLine($"Email resend: 30 sent in {sw.Elapsed.TotalSeconds:F1}s, max concurrency {max}");
 }
 static int Score(int id){long h=id;for(int i=0;i<100_000;i++)h=(h*31+i)%1_000_000_007;return(int)(h%100);}
}
static class InterlockedExtensions{public static void Max(ref int target,int value){int current;while(value>(current=Volatile.Read(ref target))&&Interlocked.CompareExchange(ref target,value,current)!=current){}}}
